package org.eclipse.rdf4j.sail.lmdb;

import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cost.EvidenceGuarantee;

/**
 * Query-local physical planning evidence derived from one Frontier state and one correlated semi/anti predicate.
 *
 * <p>
 * A sampled profile normally leaves {@link #distinctKeyEstimate()} unknown. Retained correlation keys are a lower
 * bound. A database-exact ancestor may also prove a finite upper domain when every intervening operator only duplicates
 * or removes mappings without changing the correlated values. Matching lower and upper domains then prove exact
 * distinct keys without claiming that the complete row measure is database-exact.
 */
record FrontierCorrelationProfile(
		double outerRows,
		double matchedRows,
		double unmatchedRows,
		double expectedRhsRowsExamined,
		double distinctKeyLowerBound,
		double distinctKeyEstimate,
		double distinctKeyUpperBound,
		double fanoutMean,
		double fanoutMaximum,
		EvidenceGuarantee guarantee,
		double confidence) {

	boolean hasExactDistinctKeys() {
		return Double.isFinite(distinctKeyEstimate)
				&& distinctKeyLowerBound == distinctKeyEstimate
				&& distinctKeyEstimate == distinctKeyUpperBound;
	}

	double planningDistinctKeys() {
		return hasExactDistinctKeys() ? distinctKeyEstimate : distinctKeyUpperBound;
	}
}
